"""Individually authored walkthroughs. Numeration checked against the supplied 2014 scan.
A practical drawing/measurement is never auto-certified by answering a text question.
"""
P=[]
def N(q,a,e): return dict(type='number',prompt=q,answer=str(a),explain=e)
def C(q,a,*wrong,explain): return dict(type='choice',prompt=q,answer=a,options=[a,*wrong],explain=explain)
def M(q,a,options,e): return dict(type='multi',prompt=q,answer=a,options=options,explain=e)
def W(q,e): return dict(type='written',prompt=q,explain=e)
def add(n,title,page,brief,steps,model='segments',insight='',**kw):
 P.append(dict(id=str(n),number=n,title=title,page=page,pdfPage=page+3,chapter=1,brief=brief,steps=steps,model=model,insight=insight,**kw))
add(1,'Принадлежит ли точка прямой?',7,'Построй прямую a, точки A и B на ней, а P, Q, R — вне её. Запиши принадлежность точек.',[
 C('Какая запись соответствует точке A на прямой a?','A ∈ a','A ∉ a',explain='Знак ∈ означает «принадлежит». Для B запись такая же.'),
 C('Какая запись подходит сразу для P, Q и R?','P ∉ a, Q ∉ a, R ∉ a','P ∈ a, Q ∈ a, R ∈ a',explain='Эти три точки не лежат на прямой.'),
 W('Выполни чертёж на поле и опиши, где расположены все пять точек.','Проведи прямую через A и B; точки вне прямой должны оставаться вне неё. Учитель проверит рисунок.')],insight='Начинай с двух точек, задающих прямую. Остальные не должны случайно оказаться на ней.',practical=True)
add(2,'Три точки — три прямые',7,'Отметь A, B, C, не лежащие на одной прямой. Проведи AB, BC, CA.',[
 C('Почему AB и AC — разные прямые?','C не лежит на AB','У прямых разные буквы','Все прямые всегда различны',explain='Если бы AB и AC совпали, все три точки лежали бы на одной прямой.'),
 N('Сколько различных прямых получается?',3,'Каждая из трёх пар точек задаёт свою прямую: AB, BC, CA.'),W('Проведи эти три прямые и объясни, что изменится при переносе C на AB.','При коллинеарности остаётся одна прямая, и исходное условие нарушено.')],model='triangle',practical=True)
add(3,'Одна точка пересечения или три?',7,'Проведи три различные прямые так, чтобы каждая пара пересекалась. Найди все варианты числа точек пересечения.',[
 N('Если все три проходят через одну точку, сколько различных точек пересечения?',1,'Три пары прямых пересекаются в одной и той же точке: считаем точки, а не пары.'),
 N('Если третья прямая не проходит через пересечение первых двух, сколько точек получается?',3,'У третьей прямой две разные точки пересечения с первыми двумя; ещё одна — пересечение первых двух.'),
 C('Возможны ровно две различные точки?','Нет','Да',explain='Если третья прямая пройдёт через пересечение первых двух, все пересечения совпадут. Иначе она пересечёт их в двух разных новых точках.')],model='intersections',insight='Одна картинка не исчерпывает условие. Передвинь третью прямую и найди момент совпадения трёх пересечений.')
add(4,'Когда пары дают одну и ту же прямую',8,'A, B, C лежат на одной прямой; D находится вне неё. Проведи прямую через каждую пару.',[
 N('Сколько различных прямых задают пары AB, AC, BC?',1,'Все три пары лежат на одной прямой.'),N('Сколько новых прямых дают пары AD, BD, CD?',3,'Эти прямые различны, иначе D лежала бы на исходной прямой.'),N('Всего различных прямых?',4,'Одна исходная и три через D: 1 + 3 = 4.')],model='collinear-four')
add(5,'Прямая длиннее отрезка',8,'На прямой a отмечены A, B. Размести M, N на AB; P, Q на a вне AB; R, S вне a.',[
 C('Точка на отрезке AB обязательно лежит на прямой AB?','Да','Нет',explain='Отрезок — часть этой прямой.'),C('Точка на прямой AB обязательно лежит на отрезке AB?','Нет','Да',explain='Она может находиться за одним из концов.'),W('Добавь шесть точек и запиши для каждой: на отрезке, на продолжении или вне прямой.','Для P и Q выбери продолжения за A или B; для R и S — места вне линии.')],practical=True)
add(6,'Отрезки по трём точкам',8,'На прямой отмечены три различные точки. Посчитай отрезки с концами в этих точках.',[N('Сколько концов у каждого отрезка?',2,'Нужна пара разных точек.'),N('Сколько разных пар можно выбрать из A, B, C?',3,'AB, AC, BC. Порядок букв не создаёт нового отрезка.')])
add(7,'Точка может быть и концом отрезка',8,'Точки расположены в порядке A–B–C–D (рис. 10). Укажи отрезки, содержащие C, и отрезки, не содержащие B.',[
 M('Выбери все отрезки, на которых лежит C.',['AC','AD','BC','BD','CD'],['AB','AC','AD','BC','BD','CD'],'Точка принадлежит отрезку и тогда, когда является его концом.'),
 M('Какие из этих отрезков не содержат B?',['CD'],['AB','AC','AD','BC','BD','CD'],'На CD точка B не лежит; остальные отрезки имеют B концом или внутренней точкой.')],model='four-ordered')
add(8,'Луч определяется началом и направлением',10,'На прямой точки расположены A–C–B. Сравни лучи AB, BC, CA, AC, BA; найди продолжение CA.',[
 M('Какие лучи совпадают с AB?',['AC'],['BC','CA','AC','BA'],'Начало A одно и то же; B и C задают одно направление.'),
 M('Какие лучи совпадают с BC?',['BA'],['AB','CA','AC','BA'],'Оба начинаются в B и направлены через C к A.'),C('Продолжение луча CA за начало C — это…','CB','AC','BA',explain='У дополнительных лучей общее начало C и противоположные направления.')],model='three-ordered')
add(9,'Где вершина угла?',10,'Построй три неразвёрнутых угла; обозначь их ∠AOB, ∠hk и ∠M.',[
 C('Какая вершина у ∠AOB?','O','A','B',explain='В трёхбуквенной записи вершина стоит в середине.'),C('Что означают h и k в записи ∠hk?','Два луча с общим началом','Две длины','Две вершины',explain='Двухбуквенное обозначение здесь использует названия сторон-лучей.'),W('Построй углы и подпиши их вершины и стороны.','Одной буквой M удобно обозначать угол, если выбор его сторон однозначен.')],model='angles',practical=True)
add(10,'Развёрнутый угол',10,'Построй два развёрнутых угла и обозначь их буквами.',[N('Какова градусная мера развёрнутого угла?',180,'Его стороны — противоположные лучи.'),C('Где должна лежать вершина O относительно точек A и B на сторонах?','Между A и B','За A и B с одной стороны',explain='Иначе OA и OB будут одним лучом, а не противоположными.'),W('Построй две прямые; на каждой выбери вершину и точки по обе стороны.','Например, A–O–B и C–P–D задают два развёрнутых угла.')],model='straight',practical=True)
add(11,'Углы по трём лучам',10,'Из одной точки выходят три различных луча h, k, l. Назови все углы, образованные парами лучей.',[M('Выбери все разные пары.',['hk','hl','kl'],['hk','hl','kl','hh','kk'],'Достаточно hk, hl, kl. kh обозначает тот же угол, что hk; hh не образует нужную пару разных лучей.'),N('Сколько разных пар?',3,'У каждого угла две стороны; выбираем две из трёх.')],model='three-rays')
add(12,'Внутри, снаружи, на стороне',10,'Построй неразвёрнутый угол hk. Размести по две точки внутри, снаружи и на сторонах.',[C('Точка на стороне считается внутренней точкой угла?','Нет','Да',explain='В этом задании внутреннюю область и её границу различают.'),W('Добавь шесть точек и классифицируй их.','Внутренние точки лежат между лучами; точки на лучах — на границе; остальные — снаружи.')],model='angles',practical=True)
add(13,'Весь отрезок внутри',10,'В неразвёрнутом угле размести отрезок AB целиком внутри и отрезок MN целиком снаружи.',[C('Если A и B строго внутри угла меньше 180°, где весь AB?','Внутри угла','Может выйти наружу',explain='Внутренняя область такого угла выпукла: отрезок между её точками остаётся внутри.'),C('Достаточно ли для внешнего MN выбрать любые две внешние точки?','Нет','Да',explain='Отрезок между внешними точками может пересечь угол. Возьми обе точки по одну внешнюю сторону от одной из прямых-сторон.'),W('Построй оба отрезка. Объясни, почему весь MN снаружи.','Проверь середину и весь путь от M к N, а не только концы.')],model='angles',practical=True)
add(14,'Какой луч разделит угол?',10,'Внутри ∠AOB проведи OC. Затем проведи OD, который не делит ∠AOC на две части.',[C('Что нужно для первого луча?','C строго внутри ∠AOB','C в любой точке плоскости','C на OA',explain='Луч должен начинаться в O и идти через внутреннюю область.'),C('Где можно разместить D?','Между OC и OB','Только между OA и OC',explain='Тогда OD лежит вне меньшего угла AOC, хотя остаётся внутри исходного AOB.'),W('Построй лучи и выдели меньший угол AOC.','Можно выбрать OD и совсем снаружи AOB; оба способа допустимы.')],model='three-rays',practical=True)
add(15,'Четыре угла при пересечении',10,'Две разные прямые пересекаются. Посчитай образовавшиеся неразвёрнутые углы.',[N('Сколько лучей выходит из точки пересечения?',4,'Каждая прямая даёт два противоположных луча.'),N('Сколько неразвёрнутых углов образуют эти лучи?',4,'Из 6 пар лучей две пары противоположны (развёрнутые углы); остаются 4.')],model='vertical')
add(16,'Читаем рисунок 17',10,'На рис. 17 A и M расположены между лучами h и k; B и D — на сторонах; C и N — снаружи.',[M('Какие точки внутри угла?',['A','M'],['A','B','C','D','M','N'],'A и M находятся во внутренней области.'),M('Какие точки вне угла?',['C','N'],['A','B','C','D','M','N'],'B и D не надо относить ни к внутренним, ни к внешним: они на сторонах.')],model='positions')
add(17,'Читаем рисунок 18',10,'На рис. 18 лучи h и l идут между OA и OB; k ниже OB, n выше OA, m направлен в противоположную область.',[M('Какие лучи делят ∠AOB на два угла?',['h','l'],['h','k','l','m','n'],'Начало у всех O, но только h и l проходят строго внутри AOB.')],model='inside-rays')
add(18,'Сначала восстанови порядок точек',12,'B находится между O и A, а A — между O и C. Сравни OB с OA, OC с OA и OB с OC.',[C('Каков порядок точек на луче?','O–B–A–C','O–A–B–C','O–B–C–A',explain='Сначала B, затем A, затем C.'),C('Выбери все три сравнения.','OB < OA; OC > OA; OB < OC','OB > OA; OC > OA; OB > OC','OB < OA; OC < OA; OB < OC',explain='Расстояние от общего начала увеличивается при движении вдоль луча.')],model='obac')
add(19,'Наложение половины и целого',12,'O — середина AB. Можно ли наложением совместить OA с OB, а OA с AB?',[
 C('OA и OB можно совместить?','Да','Нет',explain='Середина делит отрезок на два равных.'),C('OA и весь AB можно совместить без растяжения?','Нет','Да',explain='AB = 2·OA; наложение не изменяет длину.')],model='midpoint')
add(20,'Середины в цепочке равных отрезков',12,'A–B–C–D–E; AB = BC = CD = DE (рис. 25). Найди середины AC, AE, CE и отрезки с серединой D или C.',[
 C('Середины AC, AE, CE соответственно…','B, C, D','B, D, C','C, C, C',explain='Считаем одинаковые шаги в обе стороны от каждой середины.'),C('D — середина какого отрезка с отмеченными концами?','CE','AE','BD',explain='CD = DE, а D лежит между C и E.'),M('Какие отрезки имеют середину C?',['AE','BD'],['AB','AC','AE','BD','CE'],'CA = CE и CB = CD.')],model='five-equal')
add(21,'Часть меньше целого',13,'OC делит неразвёрнутый угол AOB на два угла. Сравни ∠AOB и ∠AOC.',[C('Как сравниваются углы?','∠AOC < ∠AOB','∠AOC = ∠AOB','∠AOC > ∠AOB',explain='К AOC нужно добавить положительный угол COB, чтобы получить AOB.')],model='angle-parts')
add(22,'Биссектриса не растягивает угол',13,'l — биссектриса ∠hk. Можно ли наложением совместить ∠hl с ∠lk, а ∠hl с ∠hk?',[
 C('∠hl и ∠lk равны?','Да','Нет',explain='Это две равные части, полученные биссектрисой.'),C('Половина ∠hl равна всему ∠hk?','Нет','Да',explain='Для ненулевого угла целое вдвое больше половины.')],model='bisector')
add(23,'Биссектрисы среди шести лучей',13,'В порядке OA, OB, OC, OD, OE, OF пять соседних углов равны (рис. 26).',[C('Биссектрисы ∠AOC, ∠BOF, ∠AOE соответственно…','OB, OD, OC','OC, OC, OD','OB, OE, OD',explain='Нужно отсчитать равное число маленьких углов слева и справа от луча.'),M('Какие углы делит пополам OC?',['AОE','BОD'],['AОE','BОD','AОF','CОD'],'До A и E по два шага, до B и D — по одному.')],model='six-rays')
add(24,'Измеряем свой экземпляр',16,'Измерь ширину и длину своего учебника. Запиши каждую в сантиметрах и миллиметрах.',[N('Сколько миллиметров в 1 сантиметре?',10,'Значение в сантиметрах умножают на 10.'),W('Ширина: … см = … мм. Длина: … см = … мм. Чем измерял(а)?','Размер зависит от экземпляра. Единого численного ответа нет; проверь, что миллиметров ровно в 10 раз больше.')],model='none',practical=True)
add(25,'Толщина одного листа',16,'Измерь толщину блока учебника без обложки. По количеству листов оцени толщину одного.',[C('Один лист обычно содержит сколько пронумерованных страниц?','Две','Одну','Четыре',explain='Страница — одна сторона листа. Учитывай также непронумерованные листы.'),C('Как получить среднюю толщину листа?','Толщину блока разделить на число листов','Разделить на число страниц','Умножить на число листов',explain='Деление на число страниц даст примерно половину толщины листа.'),W('Запиши толщину блока, число листов и результат деления с единицами.','Это приближённое измерение: толщина бумаги и сжатие блока влияют на результат.')],model='none',practical=True)
add(26,'Смена единицы длины',16,'На рис. 31: CD содержит 6 маленьких шагов, EF — 5, PQ — 3, AB — 2, KL — 1. Вырази длины сначала в KL, затем в AB.',[N('В единицах KL длина CD равна…',6,'Одна единица совпадает с маленьким шагом.'),N('В единицах KL длина EF равна…',5,'Пять одинаковых шагов.'),N('В единицах KL длина PQ равна…',3,'Три шага.'),N('В единицах KL длина AB равна…',2,'Два шага.'),N('В единицах KL длина KL равна…',1,'Любая единица содержит ровно одну себя.'),N('В единицах AB длина CD равна…',3,'В каждом AB два шага: 6 : 2.'),N('В единицах AB длина EF равна…',2.5,'5 : 2 = 2,5.'),N('В единицах AB длина PQ равна…',1.5,'3 : 2 = 1,5.'),N('В единицах AB длина AB равна…',1,'Новая единица.'),N('В единицах AB длина KL равна…',0.5,'Один шаг составляет половину AB.')],model='units')
add(27,'Удвоить и разделить длину',16,'От начала луча h отложи отрезки длиной 2AB, AB/2, AB/4.',[C('Как получить четверть AB?','Дважды разделить пополам','Отнять 4','Разделить пополам и удвоить',explain='(AB : 2) : 2 = AB : 4.'),W('Измерь AB; от одного начала луча отложи три нужные длины и подпиши их.','Удвоенный отрезок в 8 раз длиннее четверти. Все три начинаются в одной точке.')],model='scaled-segments',practical=True)
add(28,'Два последовательных середины',16,'На прямой AB найди C так, чтобы B была серединой AC, затем D — середину BC.',[C('Где C относительно A и B?','За B, причём BC = AB','Между A и B','За A',explain='B должна лежать между A и C.'),C('Длина BD в долях AB?','AB/2','AB','2AB',explain='BC = AB; середина D делит BC на две равные части.'),W('Построй C и D и запиши порядок точек.','Порядок A–B–D–C. При A = 0, B = 1 получаем D = 1,5, C = 2.')],model='abdc',practical=True)
add(29,'Расстояние не задаёт направление',16,'На прямой AB найди все точки C на расстоянии 2 см от A.',[N('Сколько направлений есть на прямой от точки A?',2,'Можно двигаться в любую из двух противоположных сторон.'),N('Сколько подходящих точек?',2,'По одной точке на расстоянии 2 см с каждой стороны A.')],model='two-directions')
add(30,'Не складывай сантиметры с миллиметрами',17,'B лежит между A и C; AB = 7,8 см, BC = 25 мм. Найди AC.',[N('BC в сантиметрах?',2.5,'25 мм : 10 = 2,5 см.'),N('AC в сантиметрах?',10.3,'B внутри AC, поэтому AC = AB + BC = 7,8 + 2,5.')],model='parts',insight='Сначала единая мера, потом сложение.')
add(31,'Из целого вычесть часть',17,'B делит AC. Найди BC: а) AB = 3,7 см, AC = 7,2 см; б) AB = 4 мм, AC = 4 см.',[N('а) BC, см?',3.5,'BC = 7,2 − 3,7.'),N('б) AC в миллиметрах?',40,'4 см = 40 мм.'),N('б) BC, мм?',36,'BC = 40 − 4.')],model='parts')
add(32,'Два положения на прямой',17,'A, B, C коллинеарны; AB = 12 см, BC = 13,5 см. Найди все значения AC.',[N('Если A и C по разные стороны от B: AC, см?',25.5,'B между A и C, поэтому длины складываются.'),N('Если A и C по одну сторону от B: AC, см?',1.5,'BC > BA, значит A между B и C; AC = 13,5 − 12.'),C('Нужно ли ещё значение −1,5 см?','Нет','Да',explain='Расстояние неотрицательно. Перестановка направления даёт тот же модуль разности.')],model='two-cases')
