add(36,'Можно ли уложить длины на прямую?',17,'AC = 5 см, AB = 3 см, BC = 4 см. Могут ли A, B, C лежать на одной прямой?',[N('Сумма двух меньших длин?',7,'3 + 4 = 7.'),C('Равна ли она наибольшей длине 5?','Нет','Да',explain='Для трёх различных коллинеарных точек наибольший отрезок равен сумме двух других.'),C('Вывод?','Точки не лежат на одной прямой','Точки лежат на одной прямой',explain='Ни одна из точек не может быть между двумя другими с указанными расстояниями.')],model='triangle')
