add(65,'Сумма двух или трёх',25,'Две прямые пересекаются. а) Сумма двух углов 114°; б) сумма трёх 220°. Найди все четыре угла.',[C('а) Два угла с суммой 114° — какие?','Вертикальные','Смежные',explain='У смежных сумма 180°, поэтому здесь вертикальная пара.'),N('а) Каждый из этой пары?',57,'114 : 2.'),N('а) Каждый из второй пары?',123,'180 − 57. Ответ: 57°, 123°, 57°, 123°.'),N('б) Не вошедший в сумму четвёртый угол?',140,'Полный оборот 360°; 360 − 220 = 140.'),N('б) Смежный к нему?',40,'Ответ: 140°, 40°, 140°, 40°.')],model='vertical')
add(66,'Систему заменяет структура рисунка',25,'На рис. 41 ∠1 = ∠3, ∠2 = ∠4. а) 2 + 4 = 220°; б) 3·(1 + 3) = 2 + 4; в) 2 − 1 = 30°.',[N('а) ∠2?',110,'220 : 2; ∠4 = 110°.'),N('а) ∠1?',70,'180 − 110; ∠3 = 70°.'),C('б) Из 3·(2∠1) = 2∠2 следует…','∠2 = 3∠1','∠2 = 6∠1','∠1 = 3∠2',explain='Сокращаем обе части на 2.'),N('б) ∠1 и ∠3?',45,'Одна + три части = 180°; одна = 45°.'),N('б) ∠2 и ∠4?',135,'3·45 = 135.'),N('в) ∠1 и ∠3?',75,'(180 − 30) : 2.'),N('в) ∠2 и ∠4?',105,'75 + 30.')],model='vertical')
add(67,'Собрать развёрнутый угол',25,'Три прямые пересекаются в O (рис. 47). ∠1 — справа над горизонталью; ∠2 — слева над горизонталью; ∠3 — между двумя наклонными лучами снизу.',[C('Чему равен угол между наклонными лучами сверху?','∠3','∠1','∠2',explain='Он вертикален углу 3.'),N('∠1 + ∠2 + ∠3, градусов?',180,'Заменим нижний угол 3 вертикальным верхним. Три верхних угла вместе образуют развёрнутый.')],model='three-lines')
add(68,'Три прямые: восстанови все сектора',25,'На рис. 48 противоположные пары лучей: OA–OD, OB–OE, OC–OF. ∠AOB = 50°, ∠FOE = 70°.',[N('∠BOC?',70,'Вертикален FOE.'),N('∠AOC?',120,'50 + 70.'),N('∠BOD?',130,'Смежен AOB: 180 − 50.'),N('∠COE?',110,'Смежен COB: 180 − 70.'),N('∠COD?',60,'AOC + COD = 180°: 180 − 120.')],model='six-opposite')
add(69,'Два перпендикуляра из одной точки?',25,'Прямая a пересекает стороны неразвёрнутого угла A в разных точках P и Q. Могут ли AP и AQ обе быть перпендикулярны a?',[C('Если бы обе были перпендикулярны a, могли бы они пересекаться?','Нет','Да',explain='Две различные прямые, перпендикулярные третьей в плоскости, не пересекаются.'),C('Что противоречит этому выводу?','Они уже пересекаются в A','Они имеют разные названия','P и Q лежат на a',explain='Следовательно, обеими перпендикулярами они быть не могут.')],model='perpendiculars')
add(70,'«По крайней мере» — сколько гарантировано?',25,'Через точку A вне прямой a проведены три различные прямые, пересекающие a. Докажи, что хотя бы две не перпендикулярны a.',[N('Сколько перпендикуляров к a может проходить через A?',1,'Если их два, они пересекутся в A, хотя перпендикуляры к одной прямой не пересекаются.'),N('Из трёх прямых сколько гарантированно не перпендикулярны?',2,'3 − 1 = 2; может оказаться и три.'),W('Запиши доказательство без опоры на измерение углов.','Через A не более одного перпендикуляра к a. Значит среди трёх различных прямых остальные как минимум две не перпендикулярны a.')],model='perpendiculars')
add(71,'Перебор без двойного счёта',26,'Даны четыре точки, никакие три не коллинеарны. Через каждую пару проведена прямая.',[N('Сколько новых пар можно взять с A?',3,'AB, AC, AD.'),N('Сколько ещё с B, не повторяя AB?',2,'BC, BD.'),N('Всего прямых?',6,'3 + 2 + 1 = 6. Разные пары не дают одну прямую, иначе на ней были бы три точки.')],model='four-general')
add(72,'Пары прямых — разные пересечения',26,'Четыре прямые попарно пересекаются; через каждую точку пересечения проходят только две прямые. Сколько точек?',[N('Сколько пар различных прямых?',6,'3 + 2 + 1.'),C('Могут ли две пары дать одну точку пересечения?','Нет по условию','Всегда могут',explain='В этой точке тогда встретились бы не менее трёх прямых, что запрещено.'),N('Число точек?',6,'Каждая из шести пар даёт отдельную точку.')],model='four-lines')
add(73,'Углы бывают составными',26,'Три различные прямые проходят через одну точку. Сколько неразвёрнутых углов образуют их лучи?',[N('Сколько лучей?',6,'По два от каждой прямой.'),N('Сколько пар различных лучей?',15,'5 + 4 + 3 + 2 + 1 = 15.'),N('Сколько из них образуют развёрнутые углы?',3,'По одной паре на каждую исходную прямую.'),N('Неразвёрнутых углов?',12,'15 − 3 = 12. Считаем и углы, составленные из нескольких видимых секторов.')],model='three-lines',insight='Не ограничивайся шестью маленькими секторами.')
add(74,'Две части и одна',26,'N лежит на MP; MP = 24 см; MN вдвое больше NP. Найди NP и NM.',[N('Сколько одинаковых частей в MP?',3,'Две в MN и одна в NP.'),N('NP, см?',8,'24 : 3.'),N('NM, см?',16,'2·8.')],model='parts')
add(75,'Снова все случаи',26,'K, L, M на одной прямой; KL = 6 см, LM = 10 см. Найди все KM.',[N('Если L между K и M: KM, см?',16,'6 + 10.'),N('Если K и M по одну сторону L: KM, см?',4,'10 − 6.'),C('Может ли M лежать между K и L?','Нет: LM > KL','Да, это третий численный ответ',explain='Длина LM = 10 больше всего KL = 6. Поэтому этот порядок невозможен.')],model='two-cases')
add(76,'Перевести цепочку равенств в части',26,'AB = a; порядок A–P–Q–B; AP = 2PQ = 2QB. Найди расстояние от A до середины QB и между серединами AP и QB.',[C('Отношение AP : PQ : QB?','2 : 1 : 1','1 : 2 : 2','2 : 2 : 1',explain='AP вдвое больше каждой из двух других частей.'),C('Пусть N — середина QB. AN равно…','7a/8','3a/4','5a/8',explain='AP = a/2, PQ = a/4, QN = a/8; сумма 7a/8.'),C('Если M — середина AP, то MN равно…','5a/8','3a/8','7a/8',explain='AM = a/4 = 2a/8, поэтому MN = 7a/8 − 2a/8 = 5a/8.')],model='ratio-parts')
add(77,'Убрать по половинке с краёв',26,'Отрезок длины m разделён на а) 3 равные части; б) 5 равных частей. Найди расстояние между серединами крайних частей.',[C('а) Сколько всего вычитается из m?','m/3','2m/3','m/6',explain='По половине части с каждого конца: две половины составляют одну часть m/3.'),C('а) Расстояние середин?','2m/3','m/3','m/2',explain='m − m/3 = 2m/3.'),C('б) Расстояние середин?','4m/5','3m/5','m/5',explain='Вычитаем две половины одной пятой: m − m/5 = 4m/5.')],model='equal-parts')
add(78,'Середины четырёх неравных частей',26,'Отрезок 36 см разделён на четыре неравные части. Расстояние между серединами крайних — 30 см. Найди расстояние между серединами двух средних.',[N('Сумма половин крайних частей, см?',6,'От целого 36 до расстояния 30 убраны половины двух крайних: 36 − 30 = 6.'),N('Сумма крайних частей, см?',12,'2·6.'),N('Сумма двух средних частей, см?',24,'36 − 12.'),N('Расстояние между серединами средних, см?',12,'Оно равно половине их суммы: 24 : 2.')],model='four-parts')
add(79,'Доказательство для двух расположений',27,'A, B, C лежат на прямой. M и N — середины AB и AC. Докажи BC = 2MN.',[C('Когда B и C по разные стороны A, MN равно…','AB/2 + AC/2','AB/2 − AC/2','AB + AC',explain='Середины тоже по разные стороны A: MN = (AB + AC)/2 = BC/2.'),C('Когда B и C по одну сторону A, MN равно…','|AB − AC|/2','(AB + AC)/2','|AB − AC|',explain='MN = |AM − AN| = |AB − AC|/2 = BC/2. Модуль учитывает любой порядок B и C.'),W('Сформулируй общий вывод, охватывающий оба случая.','В обоих случаях MN = BC/2; умножив на 2, получаем требуемое BC = 2MN. При B = C обе части равны нулю.')],model='midpoint-cases')
add(80,'Сумма или разность углов',27,'∠AOB = 35°, ∠BOC = 50°. Найди все значения ∠AOC и построй оба случая.',[N('Если OA и OC по разные стороны OB: AOC?',85,'35 + 50 = 85°, меньше 180°.'),N('Если OA и OC по одну сторону OB: AOC?',15,'50 − 35 = 15°.'),W('Построй оба случая и отметь положение общего луча OB.','Отражения всего чертежа не добавляют новых значений угла.')],model='angle-cases')
add(81,'Почему 270° не является ответом здесь',27,'∠hk = 120°, ∠hm = 150°. Найди угол km для всех расположений лучей.',[N('k и m по одну сторону h: угол km?',30,'150 − 120 = 30°.'),N('k и m по разные стороны h: сумма двух исходных углов?',270,'120 + 150 = 270° — это большая часть полного оборота.'),N('Меньший угол km во втором случае?',90,'360 − 270 = 90°. Ответы: 30° или 90°.')],model='wide-cases',insight='При сумме больше 180° оставшийся угол до полного оборота становится искомым.')
add(82,'Смежные углы с заданной разностью',27,'а) Один смежный угол на 45° больше другого; б) их разность 35°. Найди оба.',[N('а) Меньший угол в десятичных градусах?',67.5,'(180 − 45) : 2 = 67,5° = 67°30′.'),N('а) Больший?',112.5,'67,5 + 45 = 112,5° = 112°30′.'),N('б) Меньший?',72.5,'(180 − 35) : 2 = 72,5° = 72°30′.'),N('б) Больший?',107.5,'72,5 + 35 = 107,5° = 107°30′.')],model='adjacent')
add(83,'Биссектрисы смежных углов',27,'Найди угол между внутренними биссектрисами двух смежных углов.',[C('Если углы α и β, угол между их биссектрисами равен…','α/2 + β/2','α/2 − β/2','α + β',explain='Биссектрисы лежат по разные стороны общей стороны, поэтому половины складываются.'),N('Полученный угол, градусов?',90,'(α + β)/2 = 180°/2 = 90°. Биссектрисы перпендикулярны.')],model='adjacent-bisectors')
add(84,'Почему биссектрисы образуют прямую',27,'Докажи, что биссектрисы вертикальных углов лежат на одной прямой.',[C('У вертикальных углов α и α их половины…','Равны α/2','Всегда 45°','Дополняют друг друга до 90°',explain='Половины равных углов равны.'),C('Угол от одной биссектрисы до другой через соседний угол равен…','α/2 + (180° − α) + α/2','α/2 + α/2','180° − α',explain='Проходим половину первого, весь смежный и половину второго вертикального угла.'),N('Чему равна эта сумма?',180,'Половины складываются в α и сокращаются с −α.'),W('Заверши доказательство через определение развёрнутого угла.','Биссектрисы — противоположные лучи с общим началом, значит лежат на одной прямой.')],model='vertical-bisectors')
add(85,'Обратное утверждение о биссектрисах',27,'Биссектрисы ∠ABC и ∠CBD перпендикулярны. Докажи, что A, B, D коллинеарны.',[C('Могут ли BA и BD быть по одну сторону BC при таком условии?','Нет','Да',explain='Тогда угол между биссектрисами был бы модулем разности двух половин углов. Каждая половина меньше 90°, поэтому их разность не может равняться 90°.'),N('Значит сумма половин ∠ABC и ∠CBD равна…',90,'Биссектрисы находятся по разные стороны BC и перпендикулярны.'),N('Сумма полных углов?',180,'Удваиваем 90°.'),W('Почему отсюда A, B, D лежат на прямой?','BC находится между BA и BD; сумма ABC + CBD = 180°. Следовательно, ∠ABD развёрнут, BA и BD противоположны.')],model='adjacent-bisectors')
add(86,'Предположим совпадение',27,'a и b пересекаются; A вне обеих. Через A проведены m ⟂ a и n ⟂ b. Докажи m ≠ n.',[C('Если m и n совпали бы с одной прямой c, то…','a и b обе перпендикулярны c','a и b совпали бы с c','a была бы параллельна c',explain='Из m ⟂ a и n ⟂ b при m = n получаем общий перпендикуляр c.'),C('Могут ли две разные прямые a и b тогда пересекаться?','Нет','Да',explain='Две различные прямые, перпендикулярные третьей, не пересекаются.'),W('Укажи противоречие и вывод.','По условию a и b пересекаются; это противоречит следствию из m = n. Значит m и n различны.')],model='perpendiculars')
assert [p['number'] for p in P]==list(range(1,87))
